-- PsyLab V65 — La Blouse : format « Le cas qui fait débat » (3 décisions)
-- À exécuter après V64. Cette migration modifie uniquement le template 6 et le moteur de score courant.

update public.challenge_templates
set content=$json${"fr":{"title":"Le syndrome est évident. La cause ne l’est pas.","subtitle":"Reconnaître une manie ne suffit pas : encore faut-il expliquer pourquoi elle survient.","objective":"Distinguer un syndrome maniaque d’un trouble bipolaire primaire et hiérarchiser une cause médicamenteuse.","intro":"Un tableau maniaque franc apparaît pour la première fois à un âge inhabituel. Plusieurs explications restent possibles. Votre score dépendra moins du diagnostic final que de la donnée que vous choisirez de rechercher et de la façon dont vous pondérerez la causalité.","reflex":"Devant un premier syndrome maniaque tardif, identifiez le syndrome puis reconstruisez immédiatement la chronologie des médicaments, substances et causes médicales avant d’étiqueter un trouble bipolaire primaire.","debrief_intro":"Le cas testait la capacité à séparer l’identification syndromique de l’attribution étiologique. Le piège était de considérer « manie » et « trouble bipolaire I primaire » comme des synonymes.","steps":[{"kind":"rank","label":"Prendre position","question":"Avant tout examen complémentaire, comment hiérarchisez-vous les hypothèses ?","instruction":"M. N., 54 ans, sans antécédent psychiatrique connu, est amené par sa famille pour huit jours d’exaltation inhabituelle, irritabilité, réduction nette du besoin de sommeil, débit verbal accéléré, multiplication de projets et dépenses inconsidérées. Il se dit « plus lucide que jamais ». Il n’y a pas de désorientation. Son dossier mentionne le début récent d’une corticothérapie à forte dose pour une affection inflammatoire, mais la chronologie exacte n’a pas encore été reconstruite.","hypotheses":["Trouble bipolaire et apparenté induit par un médicament","Trouble bipolaire I — premier épisode maniaque","Trouble bipolaire et apparenté dû à une autre affection médicale","Trouble psychotique bref / autre psychose primaire"],"debrief":"Le syndrome maniaque est plausible, mais l’étiologie reste ouverte. L’âge de début et l’exposition médicamenteuse récente doivent empêcher une fermeture prématurée sur un trouble bipolaire primaire."},{"kind":"probe","label":"Une seule question","question":"Vous ne pouvez obtenir qu’une information avant de prendre votre décision finale. Laquelle a la plus forte valeur discriminante ?","instruction":"Choisir une donnée, c’est renoncer temporairement aux autres. Cherchez celle qui modifierait le plus directement la probabilité des hypothèses concurrentes.","choices":["Chronologie précise entre la corticothérapie et le début des symptômes, avec recherche d’épisodes spontanés antérieurs hors traitement","Antécédents familiaux détaillés de troubles de l’humeur","Dosage thyroïdien isolé","Score de sévérité maniaque","Nombre exact d’heures de sommeil chaque nuit","Description du tempérament habituel depuis l’adolescence","IRM cérébrale en première intention malgré l’absence de signe neurologique focal","Consommation habituelle de café et d’alcool sur l’année"],"responses":["La corticothérapie à forte dose a débuté douze jours avant l’évaluation. La famille situe le changement comportemental quatre jours après son introduction. Elle ne rapporte aucun épisode comparable auparavant, y compris lors de périodes de stress ou de privation de sommeil.","Aucun apparenté au premier degré n’a reçu de diagnostic bipolaire connu. Cette donnée modifie peu, à elle seule, la causalité de l’épisode actuel.","Le bilan thyroïdien reviendra normal. Utile dans le bilan étiologique, mais la temporalité médicamenteuse reste non résolue.","Le score confirme une manie d’intensité importante. Il quantifie le syndrome mais n’en explique pas l’origine.","Il dort environ trois heures par nuit et se sent reposé. Cela renforce le syndrome maniaque, mais n’aide presque pas à distinguer sa cause.","Il est habituellement méthodique, sans tempérament expansif marqué. Cela apporte du contexte, mais moins de valeur qu’une relation temporelle directe avec un médicament capable d’induire une activation.","L’imagerie pourra être discutée selon l’examen et le contexte. En l’état, elle ne répond pas d’abord à la question causale la plus immédiate.","Pas d’usage problématique rapporté. Cette information est utile mais ne résout pas la temporalité avec le traitement récent."],"debrief":"La meilleure question n’était pas celle qui documentait encore mieux la manie, mais celle qui testait directement le lien causal entre exposition médicamenteuse et apparition du syndrome."},{"kind":"final","label":"Défendre votre conclusion","question":"À partir des données disponibles, signez la formulation la plus défendable.","evidence":"La dose de corticoïde est réduite en coordination avec l’équipe somatique. Sur les quatre jours suivants, l’activation, l’insomnie sans fatigue et les comportements désinhibés régressent nettement. L’examen neurologique et le bilan thyroïdien ne montrent pas d’argument en faveur d’une cause neurologique ou endocrinienne évidente. Aucun épisode thymique antérieur n’est retrouvé à l’anamnèse collatérale.","diagnosis_choices":["Trouble bipolaire et apparenté induit par un médicament, probablement lié à la corticothérapie","Trouble bipolaire I — premier épisode maniaque primaire","Trouble bipolaire et apparenté dû à une autre affection médicale","Trouble psychotique bref"],"differential_choices":["Trouble bipolaire I primaire à reconsidérer si persistance ou récidive spontanée hors exposition","Trouble dépressif majeur","Trouble anxieux généralisé","Aucun différentiel nécessaire"],"discriminant_choices":["Relation temporelle étroite avec la corticothérapie, absence d’épisodes antérieurs et régression parallèle à la réduction du traitement","Présence d’une réduction du besoin de sommeil","Existence de dépenses impulsives","Intensité élevée du syndrome maniaque"],"change_mind_choices":["Persistance d’un syndrome maniaque complet bien au-delà de l’effet attendu du médicament ou récidive spontanée hors exposition","Découverte d’un parent éloigné ayant eu une dépression","Un score maniaque encore élevé le lendemain","Une personnalité habituellement extravertie"],"debrief":"La formulation la plus rigoureuse sépare le syndrome de son attribution causale. Le trouble bipolaire primaire reste un différentiel longitudinal, notamment si le tableau persiste au-delà de l’effet attendu du médicament ou récidive spontanément."}],"references":["DSM-5-TR — Troubles bipolaires et apparentés","Shorter Oxford Textbook of Psychiatry — évaluation de la manie","Jansson & Nordgaard — entretien psychiatrique et diagnostic différentiel"]},"en":{"title":"The syndrome is obvious. The cause is not.","subtitle":"Recognizing mania is not enough: you still have to explain why it occurred.","objective":"Distinguish a manic syndrome from primary bipolar disorder and prioritize a medication-related cause.","intro":"A clear manic syndrome appears for the first time at an unusual age. Several explanations remain plausible. Your score depends less on the final label than on the information you choose to seek and how you weigh causality.","reflex":"With a first late-onset manic syndrome, identify the syndrome, then immediately reconstruct the timeline of medications, substances and medical causes before labeling primary bipolar disorder.","debrief_intro":"The case tested your ability to separate syndromic recognition from etiological attribution. The trap was treating “mania” and “primary bipolar I disorder” as synonyms.","steps":[{"kind":"rank","label":"Take a position","question":"Before further testing, how do you rank the hypotheses?","instruction":"Mr N., 54, with no known psychiatric history, is brought by family after eight days of unusual elation, irritability, markedly reduced need for sleep, pressured speech, multiple projects and uncharacteristic spending. He says he is “clearer than ever.” There is no disorientation. His record notes recent high-dose corticosteroid treatment for an inflammatory condition, but the exact timeline has not yet been reconstructed.","hypotheses":["Substance/medication-induced bipolar and related disorder","Bipolar I disorder — first primary manic episode","Bipolar and related disorder due to another medical condition","Brief psychotic disorder / other primary psychosis"],"debrief":"The manic syndrome is plausible, but its cause remains open. Age at onset and recent medication exposure should prevent premature closure on primary bipolar disorder."},{"kind":"probe","label":"One question","question":"You may obtain only one additional piece of information before the final decision. Which has the greatest discriminating value?","instruction":"Choosing one piece of information means temporarily giving up the others. Seek the one most likely to change the probabilities of the competing hypotheses.","choices":["Exact timeline between corticosteroid exposure and symptom onset, including any previous spontaneous episodes off treatment","Detailed family history of mood disorders","Thyroid testing alone","Mania severity rating","Exact sleep duration each night","Baseline temperament since adolescence","Immediate brain MRI despite no focal neurological sign","Usual coffee and alcohol consumption over the past year"],"responses":["High-dose corticosteroids started twelve days before assessment. Family dates the behavioral change to four days after treatment began. They report no comparable prior episode, including during stress or sleep deprivation.","No first-degree relative has a known bipolar diagnosis. By itself, this changes the causal attribution only modestly.","Thyroid testing is normal. Useful in etiological work-up, but it does not resolve the medication timeline.","The score confirms substantial manic severity. It quantifies the syndrome but does not explain its cause.","He sleeps about three hours and feels rested. This strengthens the manic syndrome but barely distinguishes its cause.","He is usually methodical without a markedly expansive temperament. Contextual, but less informative than a direct temporal relationship with a capable medication.","Imaging may be considered depending on examination and context. It does not first answer the most immediate causal question here.","No problematic use is reported. Useful, but it does not resolve the recent treatment timeline."],"debrief":"The highest-value question was not the one that documented mania more thoroughly, but the one that directly tested a causal relationship between medication exposure and the syndrome."},{"kind":"final","label":"Defend your conclusion","question":"Using the available evidence, sign the most defensible formulation.","evidence":"The corticosteroid dose is reduced with the medical team. Over the next four days, activation, reduced need for sleep and disinhibited behavior clearly recede. Neurological examination and thyroid testing do not suggest an obvious neurological or endocrine cause. Collateral history reveals no previous mood episode.","diagnosis_choices":["Substance/medication-induced bipolar and related disorder, probably corticosteroid-related","Bipolar I disorder — first primary manic episode","Bipolar and related disorder due to another medical condition","Brief psychotic disorder"],"differential_choices":["Primary bipolar I disorder to reconsider if the syndrome persists or spontaneously recurs off exposure","Major depressive disorder","Generalized anxiety disorder","No differential is needed"],"discriminant_choices":["Close temporal relationship with corticosteroid exposure, no previous episodes, and parallel improvement as treatment is reduced","Reduced need for sleep","Impulsive spending","High severity of the manic syndrome"],"change_mind_choices":["Persistence of a full manic syndrome well beyond the expected medication effect or spontaneous recurrence off exposure","Finding a distant relative with depression","A high mania score the next day","An ordinarily extroverted personality"],"debrief":"The most rigorous formulation separates syndrome from causal attribution. Primary bipolar disorder remains a longitudinal differential, particularly if symptoms persist beyond the expected medication effect or recur spontaneously."}],"references":["DSM-5-TR — Bipolar and Related Disorders","Shorter Oxford Textbook of Psychiatry — assessment of mania","Jansson & Nordgaard — psychiatric interview and differential diagnosis"]}}$json$::jsonb,
    answer_key=$json${"steps":[{"kind":"rank","ranking":[0,1,2,3]},{"kind":"probe","best":0,"weights":{"0":30,"1":14,"2":18,"3":4,"4":2,"5":10,"6":8,"7":8}},{"kind":"final","diagnosis":0,"differential":0,"discriminant":0,"change_mind":0,"certainty_target":85}]}$json$::jsonb,
    max_score=100
where template_id=6 and course_key='bipolar';

-- Conserver le moteur V64 pour les autres semaines/templates.
do $do$
begin
  if to_regprocedure('public.submit_weekly_challenge_v64(text,jsonb)') is null then
    alter function public.submit_weekly_challenge(text,jsonb) rename to submit_weekly_challenge_v64;
  end if;
end
$do$;

create or replace function public.submit_weekly_challenge(p_challenge_key text,p_answers jsonb)
returns table(score integer,accepted boolean,breakdown jsonb)
language plpgsql security definer set search_path=public as $fn$
declare
  v_uid uuid:=auth.uid(); v_start timestamptz:=date_trunc('week',now()); v_expected_key text;
  v_count int; v_offset int; v_template_id int; v_key jsonb; v_existing int; v_existing_breakdown jsonb;
  a0 jsonb; a1 jsonb; a2 jsonb; k0 jsonb; k1 jsonb; k2 jsonb;
  ranking jsonb; expected_rank jsonb; i int; hierarchy int:=0; info int:=0; conclusion int:=0; revision int:=0; calibration int:=0;
  diag int; diffdiag int; disc int; chg int; init_leader int; conf int; target int; delta int; result jsonb;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  select count(*) into v_count from public.challenge_templates where course_key='bipolar';
  if v_count=0 then raise exception 'No challenge template'; end if;
  v_offset:=(extract(week from v_start)::int % v_count);
  v_expected_key:='bipolar-'||to_char(v_start,'IYYY-IW');
  if p_challenge_key<>v_expected_key then raise exception 'Challenge is not current'; end if;
  select ct.template_id,ct.answer_key into v_template_id,v_key from public.challenge_templates ct where ct.course_key='bipolar' order by ct.template_id offset v_offset limit 1;

  if v_template_id<>6 or jsonb_array_length(v_key->'steps')<>3 then
    return query select * from public.submit_weekly_challenge_v64(p_challenge_key,p_answers); return;
  end if;
  if jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>3 then raise exception 'Incomplete challenge'; end if;
  select ca.score,ca.breakdown into v_existing,v_existing_breakdown from public.challenge_attempts ca where ca.user_id=v_uid and ca.challenge_key=p_challenge_key;
  if v_existing is not null then score:=v_existing;accepted:=false;breakdown:=coalesce(v_existing_breakdown,'{}'::jsonb);return next;return; end if;

  a0:=p_answers->0; a1:=p_answers->1; a2:=p_answers->2; k0:=v_key->'steps'->0; k1:=v_key->'steps'->1; k2:=v_key->'steps'->2;
  ranking:=coalesce(a0->'ranking','[]'::jsonb); expected_rank:=k0->'ranking';
  if jsonb_array_length(ranking)<>4 then raise exception 'Invalid ranking'; end if;
  init_leader:=coalesce((ranking->>0)::int,-1);
  if (ranking->>0)::int=(expected_rank->>0)::int then hierarchy:=hierarchy+20; end if;
  if (ranking->>1)::int=(expected_rank->>1)::int then hierarchy:=hierarchy+6; end if;
  if (ranking->>2)::int=(expected_rank->>2)::int then hierarchy:=hierarchy+4; end if;

  i:=coalesce((a1->>'choice')::int,-1);
  if i<0 then raise exception 'Missing information choice'; end if;
  info:=greatest(0,least(30,coalesce((k1->'weights'->>(i::text))::int,0)));

  diag:=coalesce((a2->>'diagnosis')::int,-1); diffdiag:=coalesce((a2->>'differential')::int,-1); disc:=coalesce((a2->>'discriminant')::int,-1); chg:=coalesce((a2->>'change_mind')::int,-1);
  if diag=(k2->>'diagnosis')::int then conclusion:=conclusion+10; end if;
  if diffdiag=(k2->>'differential')::int then conclusion:=conclusion+5; end if;
  if disc=(k2->>'discriminant')::int then conclusion:=conclusion+6; end if;
  if chg=(k2->>'change_mind')::int then conclusion:=conclusion+4; end if;

  if diag=(k2->>'diagnosis')::int then revision:=8; end if;
  conf:=greatest(0,least(coalesce((a2->>'confidence')::int,50),100));
  target:=case when diag=(k2->>'diagnosis')::int then coalesce((k2->>'certainty_target')::int,85) else 50 end;
  delta:=abs(conf-target);
  calibration:=case when delta<=10 then 7 when delta<=25 then 4 when delta<=40 then 2 else 0 end;

  score:=least(100,hierarchy+info+conclusion+revision+calibration);
  result:=jsonb_build_object(
    'dimensions',jsonb_build_object('hierarchy',hierarchy,'information',info,'conclusion',conclusion,'revision',revision,'calibration',calibration),
    'template_id',v_template_id,
    'initial_leader',init_leader,
    'final_diagnosis',diag,
    'debrief_locked_until',v_start+interval '7 days'
  );
  insert into public.challenge_attempts(user_id,challenge_key,course_key,score,answers,breakdown) values(v_uid,p_challenge_key,'bipolar',score,p_answers,result);
  accepted:=true;breakdown:=result;return next;
end;$fn$;
revoke all on function public.submit_weekly_challenge(text,jsonb) from public;
grant execute on function public.submit_weekly_challenge(text,jsonb) to authenticated;

-- Le format change cette semaine : éviter de mélanger les scores V64 et V65.
delete from public.challenge_attempts
where course_key='bipolar' and challenge_key='bipolar-'||to_char(date_trunc('week',now()),'IYYY-IW');
